# Editable editorial graphics: text remains exact, separate from generated imagery.
def svg(name,title,rows):
    txt=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 850" role="img"><title>{escape(title)}</title><rect width="1200" height="850" rx="24" fill="#f8f3e5"/><text x="65" y="95" font-family="sans-serif" font-size="42" fill="#253e3a">{escape(title)}</text>']
    txt += [f'<text x="65" y="{175+j*64}" font-family="sans-serif" font-size="30" fill="#253e3a">{escape(row)}</text>' for j,row in enumerate(rows)]
    txt.append('</svg>');(E/'assets/overlays'/name).write_text('\n'.join(txt))
